questionvariables.text:
upper_limit_x:rand(3)+1;
upper_limit_y:z^(rand(2)+1);
upper_limit_z:rand(3)+1;
power_z:rand([1,3,5]);
coef_y:rand(3)+1;
question_func:coef_y*y*cos(z^(power_z));

/*Worked soln*/
ta1:int(question_func,x,0,upper_limit_x);   /*First integral wrt x*/
ta2:int(ta1,y,0,upper_limit_y);	/*Second integral wrt y*/
ta3:int(ta2,z,0,upper_limit_z);	/*Thirst integral wrt z*/
ta:decimalplaces(float(ta3),2);
